package com.example.lebiais.sonde

/**
 * Ce que le user agent dit (ou tait) de l'appareil. Quand une version n'y est
 * pas, [systeme] le dit en clair : on n'invente rien.
 */
data class Appareil(
    /** « iPhone », « iPad », « iPad (site de bureau) », « Android », « Mac »… */
    val appareil: String,
    /** « iOS 18.2 », « iPadOS 17.5 », « Android 14 », ou la raison pour laquelle on ne le sait pas. */
    val systeme: String,
    /** « Safari 18.2 », « Chrome 131 », « Safari ~16.6 » (version de Safari, pas d'iPadOS)… */
    val navigateur: String,
    /** Un appareil iOS ou iPadOS, quel que soit le navigateur (tous sont WebKit). */
    val ios: Boolean,
    /** Une réserve sur la lecture, s'il y en a une. */
    val note: String? = null,
) {
    fun resume(): String = "$appareil · $systeme · $navigateur"
}

private fun versionPointee(brute: String): String = brute.replace('_', '.')

/**
 * Lit le user agent, `navigator.platform` et `navigator.maxTouchPoints`.
 *
 * Pièges connus : l'iPad en « site de bureau » (le défaut de Safari sur iPad)
 * annonce un Mac figé (`Macintosh; Intel Mac OS X 10_15_7`) ; on le reconnaît à
 * `MacIntel` + un écran tactile. Safari 26 fige la version d'iOS du user agent à
 * 18.6. Chrome sur Android réduit le sien à `Android 10; K`.
 */
fun analyserAppareil(userAgent: String, platform: String, maxTouchPoints: Int): Appareil {
    val ua = userAgent
    val safari = Regex("""Version/(\d+(?:\.\d+)*)""").find(ua)?.groupValues?.get(1)
    val navigateur = Regex("""CriOS/(\d+)""").find(ua)?.let { "Chrome (iOS) ${it.groupValues[1]}" }
        ?: Regex("""FxiOS/(\d+)""").find(ua)?.let { "Firefox (iOS) ${it.groupValues[1]}" }
        ?: Regex("""EdgiOS/(\d+)""").find(ua)?.let { "Edge (iOS) ${it.groupValues[1]}" }
        ?: Regex("""Edg/(\d+)""").find(ua)?.let { "Edge ${it.groupValues[1]}" }
        ?: Regex("""Firefox/(\d+)""").find(ua)?.let { "Firefox ${it.groupValues[1]}" }
        ?: Regex("""Chrome/(\d+)""").find(ua)?.let { "Chrome ${it.groupValues[1]}" }
        ?: if (safari != null && "Safari" in ua) "Safari $safari" else "inconnu"
    val ipadBureau = "Macintosh" in ua && platform == "MacIntel" && maxTouchPoints > 1
    val ios = Regex("""(?:iPhone OS|CPU OS) (\d+(?:_\d+)*)""").find(ua)?.groupValues?.get(1)?.let(::versionPointee)

    if (ipadBureau) {
        return Appareil(
            "iPad (site de bureau)", "version d'iPadOS non exposée par Safari",
            if (safari != null) "Safari ~$safari" else navigateur, ios = true,
            note = "Safari sur iPad se présente comme un Mac (user agent figé) : seule la version de Safari est lisible.",
        )
    }
    val appareil = when {
        "iPhone" in ua -> "iPhone"
        "iPad" in ua -> "iPad"
        "iPod" in ua -> "iPod"
        "Android" in ua -> "Android"
        "CrOS" in ua -> "ChromeOS"
        "Macintosh" in ua -> "Mac"
        "Windows" in ua -> "Windows"
        "Linux" in ua -> "Linux"
        else -> "inconnu"
    }
    val estIos = appareil == "iPhone" || appareil == "iPad" || appareil == "iPod"
    if (estIos) {
        val nom = if (appareil == "iPad") "iPadOS" else "iOS"
        val majeurSafari = safari?.substringBefore('.')?.toIntOrNull()
        val figee = majeurSafari != null && majeurSafari >= 26 && "CriOS" !in ua && "FxiOS" !in ua
        return Appareil(
            appareil,
            when {
                ios == null -> "version d'$nom non exposée"
                figee -> "$nom $ios (valeur figée par Safari $majeurSafari)"
                else -> "$nom $ios"
            },
            navigateur, ios = true,
            note = if (figee) "Safari $majeurSafari et suivants : la version d'$nom du user agent est figée ; la version réelle n'est pas exposée." else null,
        )
    }
    val systeme = when (appareil) {
        "Android" -> {
            val m = Regex("""Android (\d+(?:\.\d+)*)(; K\))?""").find(ua)
            when {
                m == null -> "Android (version non exposée)"
                m.groupValues[2].isNotEmpty() -> "Android (version réduite par Chrome, non exposée)"
                else -> "Android ${m.groupValues[1]}"
            }
        }
        "Mac" -> "macOS (version non exposée)"
        "inconnu" -> "inconnu"
        else -> appareil
    }
    return Appareil(appareil, systeme, navigateur, ios = false)
}
