/** Un écran du menu : son titre, la phrase qui dit quoi essayer, son contenu. */
class Ecran(val titre: String, val consigne: String, val contenu: @Composable () -> Unit)

/**
 * Les écrans du menu, dans l'ordre. UNE LIGNE PAR ÉCRAN, virgule finale : les
 * tâches 3 à 6 ajoutent la leur à l'endroit de leur commentaire, sans se
 * marcher dessus. Exemple : `Ecran("Stockage", "Écrire, relire.") { EcranStockage() },`
 */
private fun ecransDeLaSonde(): List<Ecran> = listOf(
    // Parcours automatique (lot B) : l'entrée principale, en tête. Le premier de la liste (voir `Sonde`).
    Ecran("Parcours automatique", "Quelques touches, puis la sonde enchaîne seule les mesures de la grille et prépare le rapport.") { EcranParcours() },
    // Stockage (tâche 3)
    Ecran("Stockage", "Écrivez 50 Mo, relisez-les, puis demandez le stockage persistant. À refaire 8 jours plus tard, sans réécrire.") { EcranStockage() },
    Ecran("Saisie", "Saisir accents, majuscules, dictée, copier-coller ; le dernier champ doit rester au-dessus du clavier.") { EcranSaisie() },
    Ecran("Liste", "Faire défiler vite la liste des 300 bêtes et lire les images par seconde.") { EcranListe() },
    Ecran("Carte", "Glisser, pincer ou molette ; changer de fond ; lire les images par seconde et les tuiles refusées.") { EcranCarte() },
    Ecran("Photos", "Prendre ou choisir des photos : elles restent toutes en mémoire, regarder le total.") { EcranPhotos() },
    Ecran("Infos", "Lire la version, le build, les marges sûres et le temps d'ouverture ; relancer pour comparer.") { EcranInfos() },
)

private val PAPIER = Color(0xFFFFFBF2)
private val ENCRE = Color(0xFF1F1B16)

/** Les marges sûres courantes (encoche, barre d'accueil), relues à chaque rotation ou redimensionnement. */
internal val LocalMarges = compositionLocalOf { MargesSures(0.0, 0.0, 0.0, 0.0) }

/**
 * Lit les marges sûres, et les relit quand la taille de la fenêtre change (rotation,
 * redimensionnement : le canevas suit `resize`). `env()` se met à jour un instant après : deuxième lecture différée.
 */
@Composable
private fun margesSuresCourantes(): MargesSures {
    val taille = LocalWindowInfo.current.containerSize
    var marges by remember { mutableStateOf(Navigateur.margesSures()) }
    LaunchedEffect(taille) {
        marges = Navigateur.margesSures()
        delay(300)
        marges = Navigateur.margesSures()
    }
    return marges
}

/** La racine de l'interface. */
@Composable
fun Sonde() {
    val police = policeSonde()
    // Le temps d'ouverture se lit à la première image dessinée.
    LaunchedEffect(Unit) {
        withFrameNanos { }
        Ouverture.noter()
        noterOuvertureHorsLigne()
    }
    // Suivi de fluidité : les images comptées chaque seconde, et un échantillon écrit toutes les 5 s.
    // Une pause entre deux images est un gel, comptée comme telle (même de plusieurs secondes), sauf si la
    // page a été cachée pendant ce temps (arrière-plan : ce n'est pas une saccade).
    LaunchedEffect(Unit) {
        var compte = 0
        var debut = -1L
        var debutMs = 0.0
        var dernierMs = 0.0
        while (true) {
            val t = withFrameNanos { it }
            val maintenant = Navigateur.msDepuisLancement()
            val cachee = Navigateur.dernierChangementVisibilite() > dernierMs
            if (!cachee && dernierMs > 0.0) Fluidite.noterPause((maintenant - dernierMs).toInt())
            dernierMs = maintenant
            if (debut < 0L) { debut = t; debutMs = maintenant; continue }
            compte++
            val ecoule = t - debut
            if (ecoule >= 1_000_000_000L) {
                if (Navigateur.dernierChangementVisibilite() <= debutMs) {
                    Fluidite.noter((compte * 1_000_000_000L / ecoule).toInt())
                }
                compte = 0
                debut = t
                debutMs = maintenant
            }
        }
    }
    LaunchedEffect(Unit) {
        while (true) {
            delay(5000)
            Fluidite.enregistrer()
        }
    }
    MaterialTheme(typography = typographieSonde(police)) {
        val marges = margesSuresCourantes()
        val ecrans = remember { ecransDeLaSonde() }
        // Un parcours interrompu par un rechargement : on rouvre directement son écran, qui le dit en haut.
        var courant by remember {
            mutableStateOf(if (interruption(avancementGarde(), Navigateur.numeroChargement()) != null) ecrans.first() else null)
        }
        // Pendant un parcours, son écran est imposé (le menu est caché) : il pilote les écrans lui-même.
        val parcoursEnCours = MoteurParcours.enCours
        Fluidite.ecran = if (parcoursEnCours) "Parcours › ${MoteurParcours.scene.titre}" else courant?.titre ?: "Menu"
        val scopeRacine = rememberCoroutineScope()
        // L'état d'installation, relu toutes les 2 s : l'invite de Chromium arrive tard, l'installation peut se faire à côté.
        var installation by remember { mutableStateOf(Navigateur.etatInstallation()) }
        var panneauInstallation by remember { mutableStateOf(false) }
        LaunchedEffect(Unit) {
            while (true) {
                installation = Navigateur.etatInstallation()
                delay(2000)
            }
        }
        CompositionLocalProvider(LocalMarges provides marges, LocalScopeRacine provides scopeRacine) {
            Column(Modifier.fillMaxSize().background(PAPIER)) {
                Bandeau(marges, installer = if (boutonInstallerVisible(installation)) ({ panneauInstallation = !panneauInstallation }) else null)
                if (panneauInstallation && boutonInstallerVisible(installation)) {
                    PanneauInstallation(installation, marges) { panneauInstallation = false }
                }
                // Gauche, droite et bas : le contenu reste hors de l'encoche (paysage) et de la barre d'accueil.
                Column(
                    Modifier.fillMaxSize().padding(start = marges.gauche.dp, end = marges.droite.dp, bottom = marges.bas.dp),
                ) {
                    val ecran = if (parcoursEnCours) ecrans.first() else courant
                    if (ecran == null) {
                        Menu(ecrans) { courant = it }
                    } else if (parcoursEnCours) {
                        ecran.contenu()
                    } else {
                        Text(
                            "‹ Menu",
                            color = ENCRE,
                            fontSize = 16.sp,
                            modifier = Modifier.clickable { courant = null }.padding(16.dp),
                        )
                        Text(ecran.consigne, color = ENCRE, fontSize = 14.sp, modifier = Modifier.padding(horizontal = 16.dp))
                        ecran.contenu()
                    }
                }
            }
        }
    }
}

/** La version, le build et les images par seconde en permanence en haut de chaque écran, avec la mise à jour et le vidage. */
@Composable
private fun Bandeau(marges: MargesSures, installer: (() -> Unit)?) {
    Row(
        Modifier.fillMaxWidth().background(ENCRE)
            .padding(top = marges.haut.dp, start = (16 + marges.gauche).dp, end = (16 + marges.droite).dp),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        // Mise à jour forcée : repart du dernier build publié (le stockage de la sonde n'est pas touché).
        Text(
            "↻ Màj",
            color = PAPIER,
            fontSize = 14.sp,
            modifier = Modifier.clickable { Navigateur.recharger() }.padding(end = 14.dp, top = 6.dp, bottom = 6.dp),
        )
        // Libère photos, fiches et saisies gardées en mémoire, sans recharger la page.
        Text(
            "Vider",
            color = PAPIER,
            fontSize = 14.sp,
            modifier = Modifier.clickable { viderLesCaches() }.padding(end = 12.dp, top = 6.dp, bottom = 6.dp),
        )
        // Tant que la sonde n'est pas installée : ouvre les étapes (ou l'invite de Chromium).
        if (installer != null) {
            Text(
                "Installer",
                color = PAPIER,
                fontSize = 14.sp,
                modifier = Modifier.clickable { installer() }.padding(end = 12.dp, top = 6.dp, bottom = 6.dp),
            )
        }
        Spacer(Modifier.weight(1f))
        Text(
            "${Navigateur.version} · ${Navigateur.build()} · ${Fluidite.fps} i/s",
            color = PAPIER,
            fontSize = 13.sp,
            modifier = Modifier.padding(vertical = 10.dp),
        )
    }
}

/** Les étapes d'installation, sous le bandeau ; sur Chromium, le bouton qui ouvre l'invite native. */
@Composable
private fun PanneauInstallation(etat: String, marges: MargesSures, fermer: () -> Unit) {
    val appareil = remember { appareilCourant() }
    val scope = rememberCoroutineScope()
    var reponse by remember { mutableStateOf("") }
    Column(
        Modifier.fillMaxWidth().background(Color(0xFFF0E6CF))
            .padding(start = (16 + marges.gauche).dp, end = (16 + marges.droite).dp, top = 10.dp, bottom = 10.dp),
        verticalArrangement = Arrangement.spacedBy(6.dp),
    ) {
        Text("Installer la sonde", color = ENCRE, fontSize = 16.sp)
        etapesInstallation(appareil, etat).forEachIndexed { i, e -> Text("${i + 1}. $e", color = ENCRE, fontSize = 14.sp) }
        Row(horizontalArrangement = Arrangement.spacedBy(16.dp), verticalAlignment = Alignment.CenterVertically) {
            if (etat == "invite") {
                // UNDISPATCHED : prompt() part dans le geste du toucher, sinon le navigateur le refuse.
                Button(onClick = {
                    scope.launch(start = CoroutineStart.UNDISPATCHED) {
                        reponse = when (Navigateur.demanderInstallation()) {
                            "accepted" -> "Installation acceptée : ouvrir la sonde par son icône."
                            "dismissed" -> "Installation refusée."
                            else -> "Invite indisponible : passer par le menu du navigateur."
                        }
                    }
                }) { Text("Installer maintenant") }
            }
            Text("Fermer", color = ENCRE, fontSize = 14.sp, modifier = Modifier.clickable { fermer() }.padding(vertical = 8.dp))
        }
        if (reponse.isNotEmpty()) Text(reponse, color = ENCRE, fontSize = 14.sp)
    }
}

@Composable
private fun Menu(ecrans: List<Ecran>, ouvrir: (Ecran) -> Unit) {
    Column(Modifier.fillMaxSize().verticalScroll(rememberScrollState()).padding(16.dp)) {
        if (ecrans.isEmpty()) {
            Text("Aucun écran pour l'instant.", color = ENCRE)
        }
        for (e in ecrans) {
            Text(
                e.titre,
                color = ENCRE,
                fontSize = 20.sp,
                modifier = Modifier.fillMaxWidth().clickable { ouvrir(e) }.padding(vertical = 14.dp),
            )
        }
    }
}
