// Le moteur du parcours automatique (lot B) : il enchaîne les étapes du plan, pilote les écrans Liste et
// Carte par programme (l'écran est réellement affiché, les images par seconde sont vraies), et garde
// l'avancement dans localStorage à chaque étape et chaque minute. La logique pure est dans
// PlanParcours.kt, Parcours.kt et Verdicts.kt.
//
// Ce qu'un parcours piloté mesure : les images par seconde d'un défilement ou d'un déplacement animés par
// programme, pas la latence d'un vrai doigt (ni la saisie tactile).

enum class Phase { ACCUEIL, EN_COURS, QUESTIONS, FIN }

/** Réglages (localStorage, via `Navigateur.lireReglage`) : l'avancement, l'ouverture hors ligne, la durée choisie. */
const val REGLAGE_PARCOURS = "parcours"
const val REGLAGE_OUVERTURE_HORS_LIGNE = "ouvertureHorsLigne"
const val REGLAGE_DUREE = "parcoursDuree"

/** Après un déplacement de la carte, on attend au plus ce temps que toutes les tuiles visibles soient arrivées. */
const val ATTENTE_REMPLISSAGE_MAX_MS = 8000.0

/** Si la sonde s'ouvre hors ligne (mode avion), on le note avec le temps d'ouverture : lu par le verdict du point 5. */
fun noterOuvertureHorsLigne() {
    if (Navigateur.enLigneAuChargement()) return
    val ms = Ouverture.maintenant ?: return
    val o = OuvertureHorsLigne(Navigateur.dateLocale(), ms.toLong(), Navigateur.numeroChargement())
    Navigateur.ecrireReglage(REGLAGE_OUVERTURE_HORS_LIGNE, o.enTexte())
    Banc.evenement("ouverture hors ligne en ${o.ms} ms (chargement n° ${o.chargement})")
}

fun ouvertureHorsLigneNotee(): OuvertureHorsLigne? = lireOuvertureHorsLigne(Navigateur.lireReglage(REGLAGE_OUVERTURE_HORS_LIGNE))

/** L'avancement gardé dans localStorage (dernier parcours, fini ou non). */
fun avancementGarde(): Avancement? = lireAvancement(Navigateur.lireReglage(REGLAGE_PARCOURS))

/** Le rapport d'un parcours : ses étapes, ses verdicts, puis l'environnement, le relevé et les chargements de maintenant. */
suspend fun rapportDuParcours(av: Avancement): Rapport {
    val chargement = Navigateur.numeroChargement()
    return rapportCourant(etapes = etapesDuRapport(av, chargement), verdicts = verdictsDuParcours(av, chargement, ouvertureHorsLigneNotee()))
}

object MoteurParcours {
    var phase by mutableStateOf(Phase.ACCUEIL)
    /** L'écran montré sous le bandeau du parcours. */
    var scene by mutableStateOf(Scene.STATUT)
    var etape by mutableStateOf("")
    var rangEtape by mutableStateOf(0)
    /** Une phrase sur ce qui se passe (écriture, photo n/N…), montrée dans la scène « Mesures ». */
    var statut by mutableStateOf("")
    var debutMs by mutableStateOf(0.0)
    var avancement by mutableStateOf<Avancement?>(null)
        private set
    /** Les états des écrans pilotés : le parcours les passe à `EcranListe` et `EcranCarte`. */
    var etatListe by mutableStateOf(LazyListState())
        private set
    var etatCarte by mutableStateOf(EtatCarte())
        private set
    private var job: Job? = null

    val enCours: Boolean get() = phase == Phase.EN_COURS

    /**
     * Lance un parcours de [dureeMin] minutes dans [scope] (celui de la racine : il doit survivre aux écrans
     * et porter l'horloge d'images de Compose). [ecranAllume] et [installation] : l'état noté au lancement.
     */
    fun lancer(scope: CoroutineScope, dureeMin: Int, ecranAllume: String, installation: String) {
        if (job?.isActive == true) return
        val plan = planParcours(dureeMin)
        val maintenant = Navigateur.epochMs()
        // On part d'une mémoire vide : les mesures se comparent d'un parcours à l'autre.
        viderLesCaches()
        avancement = Avancement(
            plan, maintenant, maintenant, Navigateur.dateLocale(), Navigateur.numeroChargement(),
            ecranAllume = ecranAllume, installation = installation, iosIndique = Navigateur.lireReglage(Banc.REGLAGE_IOS),
        )
        sauver()
        etatListe = LazyListState()
        etatCarte = EtatCarte()
        debutMs = Navigateur.msDepuisLancement()
        scene = Scene.STATUT
        statut = ""
        phase = Phase.EN_COURS
        Banc.evenement("parcours automatique lancé : $dureeMin min · écran allumé : $ecranAllume · installation : $installation")
        job = scope.launch { executer() }
    }

    /** Arrête le parcours : l'étape en cours est abandonnée, le rapport partiel s'affiche. */
    fun arreter() { job?.cancel() }

    /** Les réponses aux questions rapides et la mesure du clavier : le parcours est fini. */
    fun terminer(reponses: Map<Question, Reponse>, clavier: MesureClavier?) {
        maj { it.copy(etat = PARCOURS_FINI, donnees = it.donnees.copy(reponses = reponses.map { (q, r) -> q.name to r.name }.toMap(), clavier = clavier)) }
        Banc.evenement("parcours fini : ${reponses.size} réponse(s)")
        phase = Phase.FIN
    }

    /** Montre le rapport d'un parcours gardé (fini, arrêté ou interrompu par un rechargement). */
    fun voir(av: Avancement) {
        avancement = av
        phase = Phase.FIN
    }

    /** Retour à l'accueil ; un parcours interrompu par un rechargement est oublié (sinon le bandeau reviendrait). */
    fun recommencer() {
        val av = avancement ?: avancementGarde()
        if (av != null && av.etat == PARCOURS_EN_COURS && job?.isActive != true) Navigateur.ecrireReglage(REGLAGE_PARCOURS, "")
        phase = Phase.ACCUEIL
    }

    private fun maintenant(): Double = Navigateur.msDepuisLancement()
    private fun ecouleS(): Int = ((maintenant() - debutMs) / 1000).toInt()

    /** Met à jour l'avancement et le garde dans localStorage. */
    private fun maj(f: (Avancement) -> Avancement) {
        val av = avancement ?: return
        avancement = f(av).copy(derniereMajEpochMs = Navigateur.epochMs())
        sauver()
    }

    private fun donnees(f: (DonneesParcours) -> DonneesParcours) = maj { it.copy(donnees = f(it.donnees)) }

    private fun sauver() { avancement?.let { Navigateur.ecrireReglage(REGLAGE_PARCOURS, it.enJson()) } }

    private suspend fun executer() {
        val plan = avancement?.plan ?: return
        try {
            for ((i, ep) in plan.etapes.withIndex()) {
                rangEtape = i
                etape = ep.etape.nom
                statut = ""
                maj { it.copy(indexEtape = i) }
                val t0 = maintenant()
                val budget = if (ep.etape == EtapeParcours.ENDURANCE) dureeEndurance(plan, ecouleS()) else ep.budgetS
                // Garde-fou : une étape qui ne rend pas la main (promesse jamais tenue) n'arrête pas le parcours.
                val limiteMs = if (ep.etape == EtapeParcours.ENDURANCE) budget * 1000L + 120_000L else budget * 3000L + 30_000L
                val faite = withTimeoutOrNull(limiteMs) { executerEtape(ep.etape, budget, plan) }
                    ?: EtapeFaite(ep.etape.nom, "délai dépassé (${limiteMs / 1000} s) : étape abandonnée", 0)
                val duree = ((maintenant() - t0) / 1000).toInt()
                maj { it.copy(etapes = it.etapes + faite.copy(dureeS = duree)) }
                Banc.evenement("parcours : ${faite.nom} — ${faite.conclusion} ($duree s)")
                scene = Scene.STATUT
            }
            maj { it.copy(indexEtape = plan.etapes.size) }
            phase = Phase.QUESTIONS
        } catch (e: CancellationException) {
            maj { it.copy(etat = PARCOURS_ARRETE) }
            Banc.evenement("parcours arrêté par le testeur à l'étape « $etape »")
            phase = Phase.FIN
            throw e
        } catch (e: Throwable) {
            maj { it.copy(etat = PARCOURS_ARRETE, etapes = it.etapes + EtapeFaite(etape, "erreur : ${e.message ?: e.toString()}", 0)) }
            Banc.evenement("parcours : erreur à l'étape « $etape » : ${e.message ?: e}")
            phase = Phase.FIN
        } finally {
            scene = Scene.STATUT
            withContext(NonCancellable) { Navigateur.ecranAllumeRelacher() }
        }
    }

    private suspend fun executerEtape(etape: EtapeParcours, budgetS: Int, plan: PlanParcours): EtapeFaite = when (etape) {
        EtapeParcours.ENVIRONNEMENT -> environnement()
        EtapeParcours.TELECHARGEMENT -> telechargement()
        EtapeParcours.STOCKAGE -> stockage()
        EtapeParcours.LISTE -> liste(budgetS, plan.court)
        EtapeParcours.CARTE -> carte(budgetS, plan.deplacementsCarte)
        EtapeParcours.FICHES -> fiches(plan.fiches)
        EtapeParcours.PHOTOS -> photos(plan.photos)
        EtapeParcours.ENDURANCE -> endurance(budgetS)
    }

    /** Note les marges sûres de l'orientation courante (une ligne par orientation vue). */
    private fun noterMarges(brut: Map<String, String>) {
        val orientation = brut["orientation"] ?: "inconnue"
        val m = Navigateur.margesSures()
        val ligne = "$orientation : haut ${m.haut.toInt()} · bas ${m.bas.toInt()} · gauche ${m.gauche.toInt()} · droite ${m.droite.toInt()}"
        val max = maxOf(m.haut, m.bas, m.gauche, m.droite).toInt()
        donnees { d ->
            if (d.marges.any { it.startsWith("$orientation :") }) d.copy(margeMaxPx = max(d.margeMaxPx, max))
            else d.copy(marges = d.marges + ligne, margeMaxPx = max(d.margeMaxPx, max))
        }
    }

    private suspend fun environnement(): EtapeFaite {
        statut = "Lecture de l'appareil et du navigateur…"
        val brut = environnementBrut()
        val appareil = appareilCourant(brut)
        noterMarges(brut)
        val m = Navigateur.margesSures()
        delay(500)
        return EtapeFaite(
            EtapeParcours.ENVIRONNEMENT.nom, "lu", 0,
            listOf(
                "Appareil (user agent)" to appareil.resume(),
                "Version d'iOS indiquée" to Navigateur.lireReglage(Banc.REGLAGE_IOS).ifBlank { "non indiquée" },
                "User agent" to (brut["userAgent"] ?: Navigateur.userAgent()),
                "Écran" to (brut["ecran"] ?: "?"),
                "devicePixelRatio" to (brut["dpr"] ?: "?"),
                "Affichage" to (brut["affichage"] ?: "?"),
                "Orientation" to (brut["orientation"] ?: "?"),
                "Marges sûres (px)" to "haut ${m.haut.toInt()} · bas ${m.bas.toInt()} · gauche ${m.gauche.toInt()} · droite ${m.droite.toInt()}",
                "Installation" to Navigateur.etatInstallation(),
                "Écran allumé" to etatEcranAllume(appareil),
                "Chargement" to "n° ${Navigateur.numeroChargement()}, ${if (Navigateur.enLigneAuChargement()) "en ligne" else "hors ligne"} à l'ouverture",
            ),
        )
    }

    private suspend fun telechargement(): EtapeFaite {
        statut = "Contrôle du précache et du poids de la page…"
        val precache = Navigateur.controlePrecache()
        val taille = Navigateur.tailleTransferee()
        val ouverture = Ouverture.maintenant
        donnees { it.copy(precacheJson = precache, tailleTransferee = taille, ouvertureMs = ouverture) }
        val horsLigne = ouvertureHorsLigneNotee()
        return EtapeFaite(
            EtapeParcours.TELECHARGEMENT.nom, verdictPrecache(precache).note, 0,
            listOf(
                "Service Worker" to Navigateur.etatServiceWorker(),
                "Précache" to lireControlePrecache(precache),
                "Taille de la page (Resource Timing)" to taille,
                "Première image (cette ouverture)" to (ouverture?.let { "${it.toLong()} ms" } ?: "pas encore mesurée"),
                "Ouverture précédente" to Ouverture.precedente.ifEmpty { "aucune" }.let { if (it == "aucune") it else "$it ms" },
                "Dernière ouverture hors ligne" to (horsLigne?.let { "${it.date}, ${it.ms} ms, chargement n° ${it.chargement}" } ?: "aucune"),
            ),
        )
    }

    /** Relit le fichier de 50 Mo écrit avec [graine] : intact ou non, et la phrase qui le dit. */
    private suspend fun relire(graine: Int): Pair<Boolean, String> {
        var debut = 0
        var ecart: Int? = null
        val r = Navigateur.lireFichier(NOM_FICHIER) { morceau ->
            if (ecart == null) ecart = Motif.premierEcart(graine, debut, morceau)
            debut += morceau.size
        }
        val attendu = MORCEAUX_A_ECRIRE.toLong() * TAILLE_MORCEAU
        return when (r) {
            is Resultat.Echec -> false to "lecture impossible : ${r.message}"
            is Resultat.Reussi -> when {
                ecart != null -> false to "faux au rang $ecart"
                r.octets != attendu -> false to "taille fausse : ${mo(r.octets)} Mo lus au lieu de ${mo(attendu)} Mo"
                else -> true to "intact : ${mo(r.octets)} Mo relus en ${r.ms.toLong()} ms"
            }
        }
    }

    private suspend fun stockage(): EtapeFaite {
        val mesures = mutableListOf<Pair<String, String>>()
        mesures += "Moyen" to Navigateur.moyenDeStockage()
        // 1. L'écriture d'avant (parcours précédent, ou écran Stockage) est relue AVANT d'être remplacée : c'est le J+8.
        val graineAvant = Navigateur.graineEcrite()
        val dateAvant = Navigateur.dateDerniereEcriture()
        if (graineAvant >= 0) {
            statut = "Relecture de l'écriture du $dateAvant…"
            val (intacte, detail) = relire(graineAvant)
            val age = joursEntre(dateAvant, Navigateur.dateLocale())
            donnees { it.copy(ancienneEcriture = dateAvant, ancienneAgeJours = age, ancienneIntacte = intacte) }
            mesures += "Écriture précédente" to "du $dateAvant (${age ?: "?"} jours) : $detail"
        } else {
            mesures += "Écriture précédente" to "aucune"
        }
        // 2. Écrire 50 Mo.
        statut = "Écriture de $SEUIL_STOCKAGE_MO Mo…"
        val graine = Navigateur.graineDuJour()
        val r = ecrireAvec(Navigateur.ecrivain, MORCEAUX_A_ECRIRE) { rang -> Motif.bloc(graine, rang * TAILLE_MORCEAU, TAILLE_MORCEAU) }
        when (r) {
            is Resultat.Reussi -> {
                Navigateur.noterDerniereEcriture(graine)
                donnees { it.copy(ecritureOk = true, ecritureDetail = "${mo(r.octets)} Mo en ${r.ms.toLong()} ms") }
                mesures += "Écriture" to "${mo(r.octets)} Mo en ${r.ms.toLong()} ms"
            }
            is Resultat.Echec -> {
                Navigateur.oublierDerniereEcriture()
                donnees { it.copy(ecritureOk = false, ecritureDetail = r.message) }
                mesures += "Écriture" to "refusée : ${r.message}"
            }
        }
        // 3. Relire, 4. persistance, 5. estimation.
        if (r is Resultat.Reussi) {
            statut = "Relecture des $SEUIL_STOCKAGE_MO Mo…"
            val (intacte, detail) = relire(graine)
            donnees { it.copy(relectureIntacte = intacte, relectureDetail = detail) }
            mesures += "Relecture" to detail
        }
        statut = "Demande du stockage persistant…"
        val persistance = Navigateur.demanderPersistance()
        val estimation = Navigateur.estimation()
        donnees { it.copy(persistance = persistance, estimation = estimation) }
        mesures += "Stockage persistant" to persistance
        mesures += "Estimation" to estimation
        val d = avancement?.donnees ?: DonneesParcours()
        return EtapeFaite(EtapeParcours.STOCKAGE.nom, verdictStockage(d).verdict, 0, mesures)
    }

    /** Attend que l'écran piloté soit dessiné. */
    private suspend fun images(n: Int) = repeat(n) { withFrameNanos { } }

    private suspend fun liste(budgetS: Int, court: Boolean): EtapeFaite {
        scene = Scene.LISTE
        val etat = etatListe
        images(3)
        withTimeoutOrNull(3000) { while (etat.layoutInfo.totalItemsCount == 0) withFrameNanos { } }
        var vues = 0
        val mesure = coroutineScope {
            // La dernière bête vue : le défilement doit atteindre le bas de la liste.
            val suivi = launch {
                while (isActive) {
                    withFrameNanos { }
                    val derniere = etat.layoutInfo.visibleItemsInfo.lastOrNull()?.index ?: -1
                    vues = max(vues, derniere + 1)
                }
            }
            val r = Fluidite.mesurer { f ->
                val fin = maintenant() + budgetS * 1000.0
                var sens = 1f
                while (fin - maintenant() > 500) {
                    val info = etat.layoutInfo
                    val hauteur = info.visibleItemsInfo.map { it.size }.average().takeIf { !it.isNaN() } ?: 60.0
                    val total = (hauteur * info.totalItemsCount * 1.1).toFloat()
                    val prevu = if (sens > 0) (if (court) 7000 else 8000) else 4000
                    val duree = min(prevu.toDouble(), fin - maintenant()).toInt()
                    statut = if (sens > 0) "Défilement vers le bas…" else "Retour en haut…"
                    etat.animateScrollBy(total * sens, tween(duree, easing = LinearEasing))
                    sens = -sens
                }
                f.resultat()
            }
            suivi.cancel()
            r
        }
        donnees { it.copy(liste = mesure, listeBetesVues = vues) }
        return EtapeFaite(
            EtapeParcours.LISTE.nom, verdictFluiditeListe(mesure, vues).verdict, 0,
            listOf("Images par seconde (défilement piloté)" to mesure.enTexte(), "Bêtes parcourues" to "$vues sur ${etat.layoutInfo.totalItemsCount}"),
        )
    }

    /** Joue un déplacement scripté image par image ; [dpr] : un px CSS vaut [dpr] px du canevas. */
    private suspend fun jouer(etat: EtatCarte, d: Deplacement, dpr: Double) {
        val debut = maintenant()
        var fait = 0.0
        while (fait < 1.0) {
            withFrameNanos { }
            val p = min(1.0, (maintenant() - debut) / d.dureeMs)
            val dp = p - fait
            val l = etat.taille.width.toDouble()
            val h = etat.taille.height.toDouble()
            etat.cadrage = when (d) {
                is Glisser -> etat.cadrage.glisse(d.dx * dpr * dp, d.dy * dpr * dp, l, h)
                is Zoomer -> etat.cadrage.pince(d.facteur.pow(dp))
            }
            fait = p
        }
    }

    /** Le temps (ms) jusqu'à ce que toutes les tuiles visibles soient arrivées, reçues ou refusées ; null passé l'attente maximale. */
    private suspend fun remplissage(etat: EtatCarte): Double? {
        val t0 = maintenant()
        images(2) // la composition voit le nouveau cadrage et demande ses tuiles
        while (maintenant() - t0 < ATTENTE_REMPLISSAGE_MAX_MS) {
            if (etat.memoire.toutesArrivees()) return maintenant() - t0
            withFrameNanos { }
        }
        return null
    }

    private suspend fun carte(budgetS: Int, deplacements: Int): EtapeFaite {
        scene = Scene.CARTE
        val etat = etatCarte
        withTimeoutOrNull(3000) { while (etat.taille.width == 0) withFrameNanos { } }
        val dpr = environnementBrut()["dpr"]?.toDoubleOrNull() ?: 1.0
        statut = "Premier remplissage…"
        val initial = remplissage(etat)
        val temps = mutableListOf<Double?>()
        val mesure = Fluidite.mesurer { f ->
            val fin = maintenant() + budgetS * 1000.0
            for ((i, d) in trajetCarte(deplacements).withIndex()) {
                if (maintenant() >= fin) break
                statut = "Déplacement ${i + 1}/$deplacements"
                jouer(etat, d, dpr)
                temps += remplissage(etat)
                delay(300)
            }
            f.resultat()
        }
        val resume = resumeRemplissage(temps)
        val recues = etat.memoire.recues
        val refusees = etat.memoire.refusees
        donnees { it.copy(carte = mesure, remplissagesMs = temps, tuilesRecues = recues, tuilesRefusees = refusees) }
        return EtapeFaite(
            EtapeParcours.CARTE.nom, verdictFluiditeCarte(mesure, resume, recues, refusees).verdict, 0,
            listOf(
                "Images par seconde (trajet piloté)" to mesure.enTexte(),
                "Remplissage après chaque déplacement" to resume.enTexte(),
                "Premier remplissage" to (initial?.let { "${it.toLong()} ms" } ?: "non rempli en ${(ATTENTE_REMPLISSAGE_MAX_MS / 1000).toInt()} s"),
                "Tuiles" to "$recues reçues · $refusees refusées",
                "Déplacements joués" to "${temps.size} sur $deplacements",
            ),
        )
    }

    private suspend fun fiches(n: Int): EtapeFaite {
        scene = Scene.SAISIE
        images(5)
        statut = "$n fiches au hasard…"
        val avant = nombreFiches()
        return try {
            val r = creerFichesAuHasard(n)
            donnees { it.copy(fichesVoulues = n, fichesCreees = nombreFiches() - avant) }
            delay(1500) // le compteur de fiches se voit à l'écran
            EtapeFaite(EtapeParcours.FICHES.nom, r.verdict, 0, r.mesures)
        } catch (e: CancellationException) {
            throw e
        } catch (e: Throwable) {
            donnees { it.copy(fichesVoulues = n, fichesCreees = nombreFiches() - avant, fichesErreur = e.message ?: e.toString()) }
            EtapeFaite(EtapeParcours.FICHES.nom, "erreur : ${e.message ?: e}", 0)
        }
    }

    private suspend fun photos(n: Int): EtapeFaite {
        scene = Scene.PHOTOS
        images(5)
        val avant = nombrePhotos()
        val r = seriePhotosSynthetiques(n) { statut = it }
        val faites = nombrePhotos() - avant
        val arret = if (r.verdict.startsWith("arrêtée")) r.verdict.substringAfter(" : ") else ""
        val decodes = (octetsDecodesPhotos() / 1_048_576L).toInt()
        donnees { it.copy(photosVoulues = n, photosFaites = faites, photosArret = arret, decodesMaxMo = max(it.decodesMaxMo, decodes)) }
        return EtapeFaite(EtapeParcours.PHOTOS.nom, r.verdict, 0, r.mesures)
    }

    /** Pendant l'endurance, ce que fait l'écran montré : la liste défile, la carte glisse ; les autres restent affichés. */
    private fun animer(scope: CoroutineScope, scene: Scene, dpr: Double): Job? = when (scene) {
        Scene.LISTE -> scope.launch {
            images(3)
            var sens = 1f
            while (isActive) {
                etatListe.animateScrollBy(2500f * sens, tween(3000, easing = LinearEasing))
                sens = -sens
            }
        }
        Scene.CARTE -> scope.launch {
            images(3)
            var sens = 1.0
            while (isActive) {
                if (etatCarte.taille.width > 0) jouer(etatCarte, Glisser(150.0 * sens, 80.0 * sens, 1500), dpr)
                delay(500)
                sens = -sens
            }
        }
        else -> null
    }

    private suspend fun endurance(dureeS: Int): EtapeFaite {
        val dpr = environnementBrut()["dpr"]?.toDoubleOrNull() ?: 1.0
        val echeancier = Echeancier()
        val totale = FenetreMesure()
        var minute = FenetreMesure()
        var rang = 0
        var fichesAjoutees = 0
        var photosAjoutees = 0
        val debut = maintenant()
        coroutineScope {
            Fluidite.fenetres.add(totale)
            Fluidite.fenetres.add(minute)
            var anim: Job? = null
            try {
                scene = sceneEndurance(rang)
                anim = animer(this, scene, dpr)
                while (true) {
                    val s = (maintenant() - debut) / 1000
                    if (s >= dureeS) break
                    statut = "Endurance : ${s.toInt() / 60} min ${s.toInt() % 60} s sur ${dureeS / 60} min ${dureeS % 60} s"
                    for (a in echeancier.echues(s)) when (a) {
                        ActionEndurance.NAVIGUER -> {
                            anim?.cancel()
                            scene = sceneEndurance(++rang)
                            anim = animer(this, scene, dpr)
                        }
                        ActionEndurance.FICHES -> {
                            creerFichesAuHasard(FICHES_PAR_AJOUT, noter = false)
                            fichesAjoutees += FICHES_PAR_AJOUT
                        }
                        ActionEndurance.PHOTO -> {
                            val r = seriePhotosSynthetiques(1, noter = false)
                            if (r.verdict.startsWith("fini")) photosAjoutees++
                            donnees { it.copy(decodesMaxMo = max(it.decodesMaxMo, (octetsDecodesPhotos() / 1_048_576L).toInt())) }
                        }
                        ActionEndurance.POINT_DE_CONTROLE -> {
                            val r = minute.resultat()
                            Fluidite.fenetres.remove(minute)
                            minute = FenetreMesure()
                            Fluidite.fenetres.add(minute)
                            pointDeControle(r)
                            donnees { it.copy(enduranceS = ((maintenant() - debut) / 1000).toInt(), endurancePauseMaxMs = totale.resultat().pauseMaxMs) }
                        }
                    }
                    delay(250)
                }
            } finally {
                anim?.cancel()
                Fluidite.fenetres.remove(totale)
                Fluidite.fenetres.remove(minute)
            }
        }
        val r = totale.resultat()
        val duree = ((maintenant() - debut) / 1000).toInt()
        donnees { it.copy(enduranceS = duree, endurancePauseMaxMs = r.pauseMaxMs) }
        val points = avancement?.points?.size ?: 0
        return EtapeFaite(
            EtapeParcours.ENDURANCE.nom, "fini : $points point(s) de contrôle", 0,
            listOf(
                "Durée" to "${duree / 60} min ${duree % 60} s",
                "Images par seconde" to r.enTexte(),
                "Écrans visités" to "${rang + 1} (un toutes les $NAVIGATION_TOUTES_LES_S s)",
                "Fiches ajoutées" to "$fichesAjoutees (${nombreFiches()} en mémoire)",
                "Photos ajoutées" to "$photosAjoutees (${nombrePhotos()} en mémoire, ${mo(octetsDecodesPhotos())} Mo décodés)",
                "Chargement" to "n° ${Navigateur.numeroChargement()}",
            ),
        )
    }

    private fun pointDeControle(r: FluiditeMesuree) {
        val brut = environnementBrut()
        noterMarges(brut)
        val n = (avancement?.points?.size ?: 0) + 1
        val p = PointDeControle(
            minute = n, fps = r.moyenne, fpsMin = r.min, pauseMaxMs = r.pauseMaxMs,
            photos = nombrePhotos(), fiches = nombreFiches(), decodesMo = (octetsDecodesPhotos() / 1_048_576L).toInt(),
            tuilesRecues = etatCarte.memoire.recues, tuilesRefusees = etatCarte.memoire.refusees,
            chargement = Navigateur.numeroChargement(), orientation = brut["orientation"] ?: "",
        )
        maj { it.copy(points = it.points + p) }
        Banc.evenement("point de contrôle ${p.enTexte()}")
    }
}
