package com.example.lebiais.sonde

// La logique pure des outils de test (lot A) : événements du relevé, séries de
// fiches, garde-fou des photos synthétiques, écran allumé, installation.

/** Une ligne d'événement du relevé : « heure|événement|texte ». `Echantillon.lire` l'ignore (trois champs). */
fun ligneEvenement(heure: String, texte: String): String = "$heure|événement|${texte.replace('|', '/')}"

/** Les événements du relevé, dans l'ordre : « heure · texte ». */
fun evenementsDuReleve(lignes: List<String>): List<String> = lignes.mapNotNull { l ->
    val p = l.split('|', limit = 3)
    if (p.size == 3 && p[1] == "événement") "${p[0]} · ${p[2]}" else null
}

/** [n] fiches au hasard, aux graines successives à partir de [graineDepart]. */
fun fichesAuHasard(n: Int, graineDepart: Int): List<List<String>> = (graineDepart until graineDepart + n).map(::ficheAleatoire)

/**
 * Le garde-fou d'une série de photos synthétiques : on arrête si les images par
 * seconde restent sous [fpsMin] plus de [dureeMaxMs], ou si la mémoire décodée
 * dépasse [octetsMax]. Rend la raison de l'arrêt, ou null pour continuer.
 */
class GardeFou(
    private val fpsMin: Int = 10,
    private val dureeMaxMs: Double = 3000.0,
    private val octetsMax: Long = 800L * 1_048_576L,
) {
    private var basDepuis: Double? = null

    fun verifier(tMs: Double, fps: Int, octetsDecodes: Long): String? {
        if (octetsDecodes > octetsMax) {
            return "plus de ${octetsMax / 1_048_576L} Mo décodés en mémoire (${mo(octetsDecodes)} Mo) : série arrêtée"
        }
        if (fps >= fpsMin) {
            basDepuis = null
            return null
        }
        val depuis = basDepuis ?: tMs.also { basDepuis = it }
        return if (tMs - depuis > dureeMaxMs) {
            "moins de $fpsMin images par seconde pendant plus de ${(dureeMaxMs / 1000).toInt()} s : série arrêtée"
        } else null
    }
}

/**
 * L'état du verrou d'écran (Wake Lock) tel que sonde.js le rend (« actif », « refusé : … »,
 * « indisponible », « relâché »…), avec le mode d'affichage. Sur iOS, en app d'écran
 * d'accueil, Wake Lock ne marche qu'à partir d'iOS 18.4 : on le rappelle, sans prétendre
 * connaître la version, que le navigateur ne mesure pas toujours.
 */
fun messageEcranAllume(etat: String, autonome: Boolean, appareil: Appareil): String {
    val base = "$etat (${if (autonome) "app d'écran d'accueil" else "onglet"})"
    if (!autonome || !appareil.ios) return base
    return when {
        etat.startsWith("actif") ->
            "$base ; sur iOS avant 18.4, l'écran peut s'éteindre quand même dans une app d'écran d'accueil : à vérifier à l'œil"
        etat.startsWith("refusé") || etat.startsWith("indisponible") ->
            "$base ; sur iOS avant 18.4, Wake Lock échoue dans une app d'écran d'accueil (défaut de WebKit corrigé en 18.4)"
        else -> base
    }
}

/**
 * États d'installation rendus par sonde.js : « autonome » (ouverte depuis l'icône),
 * « installee » (installée, page restée dans l'onglet), « invite » (invite de Chromium
 * disponible), « manuelle » (pas d'invite : Partager sur iOS, menu ailleurs).
 */
fun boutonInstallerVisible(etat: String): Boolean = etat == "manuelle" || etat == "invite"

/** Les étapes à suivre pour installer la sonde, selon l'appareil et l'état d'installation. */
fun etapesInstallation(appareil: Appareil, etat: String): List<String> = when {
    etat == "invite" -> listOf(
        "Toucher « Installer maintenant » : le navigateur propose d'installer la sonde.",
        "Puis ouvrir la sonde par sa nouvelle icône.",
    )
    appareil.ios -> listOf(
        "Ouvrir cette page dans Safari (pas dans une autre application).",
        "Toucher Partager (le carré d'où sort une flèche : en bas sur iPhone, en haut à droite sur iPad).",
        "Choisir « Sur l'écran d'accueil », puis « Ajouter ».",
        "Ouvrir la sonde par sa nouvelle icône : les données de l'onglet et celles de l'icône sont séparées, tous les essais se font depuis l'icône.",
    )
    else -> listOf(
        "Ouvrir le menu du navigateur (les trois points) et choisir « Installer l'application » ou « Ajouter à l'écran d'accueil ».",
        "Puis ouvrir la sonde par sa nouvelle icône.",
    )
}
