package com.example.lebiais.sonde

import kotlinx.serialization.Serializable

// Le plan du parcours automatique (lot B) : logique pure, sans navigateur.
// Les étapes fixes ont un budget estimé ; l'endurance prend tout le reste de la durée choisie.

/** Les durées proposées au testeur, en minutes. */
val DUREES_PARCOURS = listOf(3, 10, 20)

/** Jusqu'à cette durée (minutes), chaque étape prend sa version courte. */
const val DUREE_COURTE_MAX_MIN = 3

/** L'endurance ne descend jamais sous ce temps (s), même si les étapes d'avant ont débordé. */
const val ENDURANCE_MIN_S = 30

/** Pendant l'endurance : un autre écran toutes les 10 s, 10 fiches toutes les 30 s, une photo et un point de contrôle par minute. */
const val NAVIGATION_TOUTES_LES_S = 10
const val FICHES_TOUTES_LES_S = 30
const val FICHES_PAR_AJOUT = 10
const val PHOTO_TOUTES_LES_S = 60
const val POINT_DE_CONTROLE_TOUTES_LES_S = 60

@Serializable
enum class EtapeParcours(val nom: String) {
    ENVIRONNEMENT("Environnement"),
    TELECHARGEMENT("Téléchargement et précache"),
    STOCKAGE("Stockage (50 Mo)"),
    LISTE("Liste de 300 bêtes"),
    CARTE("Carte"),
    FICHES("Fiches au hasard"),
    PHOTOS("Photos synthétiques"),
    ENDURANCE("Endurance"),
}

@Serializable
data class EtapePlan(val etape: EtapeParcours, val budgetS: Int)

@Serializable
data class PlanParcours(
    val dureeMin: Int,
    val etapes: List<EtapePlan>,
    /** Fiches créées d'un coup à l'étape Fiches. */
    val fiches: Int,
    /** Photos synthétiques de 12 Mpx à l'étape Photos (le garde-fou peut arrêter avant). */
    val photos: Int,
    /** Déplacements scriptés de la carte (glisser, zoom avant, zoom arrière). */
    val deplacementsCarte: Int,
) {
    val court: Boolean get() = dureeMin <= DUREE_COURTE_MAX_MIN
    fun budget(etape: EtapeParcours): Int = etapes.firstOrNull { it.etape == etape }?.budgetS ?: 0
    fun enTexte(): String = etapes.joinToString(" · ") { "${it.etape.nom} ${it.budgetS} s" }
}

/** Le plan pour [dureeMin] minutes (3, 10 ou 20) : la somme des budgets fait exactement la durée. */
fun planParcours(dureeMin: Int): PlanParcours {
    require(dureeMin in DUREES_PARCOURS) { "durée de parcours inconnue : $dureeMin min (3, 10 ou 20)" }
    val court = dureeMin <= DUREE_COURTE_MAX_MIN
    // Budgets estimés (s) : environnement, téléchargement, stockage, liste, carte, fiches, photos.
    val budgets = if (court) listOf(5, 5, 25, 15, 30, 10, 30) else listOf(5, 5, 40, 20, 60, 10, 90)
    val fixes = EtapeParcours.entries.dropLast(1).zip(budgets) { e, b -> EtapePlan(e, b) }
    val endurance = EtapePlan(EtapeParcours.ENDURANCE, dureeMin * 60 - budgets.sum())
    return PlanParcours(
        dureeMin, fixes + endurance,
        fiches = 100,
        photos = if (court) 10 else 30,
        deplacementsCarte = if (court) 6 else 12,
    )
}

/**
 * La durée réelle de l'endurance quand elle commence, [ecouleS] secondes après le lancement : le
 * reste de la durée choisie, jamais moins de [ENDURANCE_MIN_S].
 */
fun dureeEndurance(plan: PlanParcours, ecouleS: Int): Int = maxOf(ENDURANCE_MIN_S, plan.dureeMin * 60 - ecouleS)

/** Ce que l'endurance fait à une échéance. */
enum class ActionEndurance { NAVIGUER, FICHES, PHOTO, POINT_DE_CONTROLE }

/**
 * Les échéances de l'endurance. [echues] rend les actions dont l'heure est venue à [secondes]
 * depuis le début de l'endurance, chacune une seule fois même si l'on a pris du retard (une
 * photo de 12 Mpx bloque l'écran) ; la suivante est alors reportée d'une période à partir de maintenant.
 */
class Echeancier {
    private val periodes = mapOf(
        ActionEndurance.NAVIGUER to NAVIGATION_TOUTES_LES_S,
        ActionEndurance.FICHES to FICHES_TOUTES_LES_S,
        ActionEndurance.PHOTO to PHOTO_TOUTES_LES_S,
        ActionEndurance.POINT_DE_CONTROLE to POINT_DE_CONTROLE_TOUTES_LES_S,
    )
    private val prochaines = periodes.mapValues { it.value.toDouble() }.toMutableMap()

    fun echues(secondes: Double): List<ActionEndurance> = ActionEndurance.entries.filter { a ->
        val prochaine = prochaines.getValue(a)
        if (secondes < prochaine) return@filter false
        val periode = periodes.getValue(a)
        // À l'heure : l'échéance suivante garde le rythme ; en retard d'une période ou plus : on repart de maintenant.
        prochaines[a] = if (secondes - prochaine < periode) prochaine + periode else secondes + periode
        true
    }
}

/** Ce que l'écran du parcours montre pendant une étape. */
enum class Scene(val titre: String) {
    STATUT("Mesures"), LISTE("Liste"), CARTE("Carte"), SAISIE("Saisie"), PHOTOS("Photos"), INFOS("Infos"),
}

/** L'écran montré au [rang]-ième changement de l'endurance : Liste, Carte, Saisie, Photos, Infos, puis on recommence. */
fun sceneEndurance(rang: Int): Scene = SCENES_ENDURANCE[rang.mod(SCENES_ENDURANCE.size)]

private val SCENES_ENDURANCE = listOf(Scene.LISTE, Scene.CARTE, Scene.SAISIE, Scene.PHOTOS, Scene.INFOS)

/** Un déplacement scripté de la carte, joué pendant [dureeMs]. */
sealed interface Deplacement {
    val dureeMs: Int
}

/** Glisser de ([dx], [dy]) px CSS (le moteur les multiplie par devicePixelRatio). */
data class Glisser(val dx: Double, val dy: Double, override val dureeMs: Int = DUREE_DEPLACEMENT_MS) : Deplacement

/** Pincer d'un [facteur] (2 = zoom avant d'un niveau, 0,5 = zoom arrière d'un niveau). */
data class Zoomer(val facteur: Double, override val dureeMs: Int = DUREE_DEPLACEMENT_MS) : Deplacement

const val DUREE_DEPLACEMENT_MS = 1200

/** Les [n] premiers déplacements du trajet de la carte ; le motif de 12 revient à son zoom de départ. */
fun trajetCarte(n: Int): List<Deplacement> = List(n) { MOTIF_CARTE[it % MOTIF_CARTE.size] }

/** Glisser dans les quatre sens, deux zooms avant, deux arrière, puis un aller-retour : zoom net nul. */
private val MOTIF_CARTE: List<Deplacement> = listOf(
    Glisser(300.0, 0.0), Glisser(0.0, 300.0), Zoomer(2.0), Glisser(-300.0, 0.0),
    Zoomer(2.0), Glisser(0.0, -300.0), Zoomer(0.5), Glisser(300.0, 300.0),
    Zoomer(0.5), Glisser(-300.0, -300.0), Zoomer(2.0), Zoomer(0.5),
)
