package com.example.lebiais.sonde

import androidx.compose.ui.graphics.ImageBitmap

/**
 * Tout ce que la sonde demande au navigateur. Chaque fonction d'un `actual`
 * ne fait qu'appeler `window.sonde.<nom>(…)` : le JavaScript vit dans
 * `web/sonde.js`, et nulle part ailleurs.
 *
 * Une section par tâche du plan, une fonction par ligne : on ajoute à la fin
 * de sa section, sans toucher aux autres.
 */
expect object Navigateur {
    // ---- Socle (tâche 2) ----
    /** "wasm" ou "js", fixé par la cible. */
    val version: String
    /** navigator.standalone ou display-mode standalone. */
    fun estInstallee(): Boolean
    /** env(safe-area-inset-*) en px CSS. */
    fun margesSures(): MargesSures
    /** performance.now() */
    fun msDepuisLancement(): Double
    /** Lu dans window.SONDE_BUILD. */
    fun build(): String

    // ---- Stockage (tâche 3) ----
    /** La version réelle de l'écrivain, par sonde.js ; lève l'erreur du navigateur. */
    val ecrivain: Ecrivain
    suspend fun lireFichier(nom: String, parMorceau: (ByteArray) -> Unit): Resultat
    /** "accordée", "refusée" ou "indisponible". */
    suspend fun demanderPersistance(): String
    /** "utilisé X Mo sur Y Mo", ou "indisponible". */
    suspend fun estimation(): String
    /** "OPFS" ou "IndexedDB". */
    fun moyenDeStockage(): String
    /** Le jour de l'année : la graine d'une NOUVELLE écriture. */
    fun graineDuJour(): Int
    /** La graine de la dernière écriture réussie (localStorage), avec laquelle on relit ; -1 si aucune. */
    fun graineEcrite(): Int
    /** Date de la dernière écriture, gardée dans localStorage ; "" si aucune. */
    fun dateDerniereEcriture(): String
    /** Note la date du jour et la [graine] qui vient d'être écrite. */
    fun noterDerniereEcriture(graine: Int)
    /** Efface la date et la graine : l'écriture a échoué, le fichier n'est plus fiable. */
    fun oublierDerniereEcriture()

    // ---- Carte et photos (tâche 5) ----
    /** Les octets d'une tuile, ou null si le serveur la refuse (CORS, réseau, statut). */
    suspend fun telechargerTuile(url: String): ByteArray?
    /**
     * Ouvre le sélecteur de photos du système ; null si l'on annule. [capture] : l'appareil photo
     * directement. À appeler SANS suspension préalable depuis le clic (voir `CoroutineStart.UNDISPATCHED`) :
     * le sélecteur doit s'ouvrir dans le geste de l'utilisateur.
     */
    suspend fun choisirPhoto(capture: Boolean): PhotoChoisie?
    /** Décodage par Skia ; null quand le format n'est pas lu (HEIC, par exemple). */
    fun decoderImage(octets: ByteArray): ImageBitmap?

    // ---- Coque installable (tâche 6) ----
    fun userAgent(): String
    /** Temps d'ouverture de la fois d'avant, en ms (localStorage) ; "" si aucune. */
    fun ouvertureMemorisee(): String
    fun noterOuverture(ms: Double)
    /** "accordée", "non accordée" ou "indisponible". */
    suspend fun persistanceActuelle(): String
    /** État du Service Worker : actif, en attente d'un nouveau build, etc. */
    suspend fun etatServiceWorker(): String
    /** Mise à jour forcée : retire le Service Worker et les caches de la sonde puis recharge (sans toucher au stockage). */
    fun recharger()
    /** Heure locale « hh:mm:ss ». */
    fun heure(): String
    /** Ajoute une ligne au relevé (localStorage, 600 lignes au plus) ; ignorée si la page est cachée. */
    fun releveAjouter(ligne: String)
    /** Les lignes du relevé, une par ligne de texte. */
    fun releveLire(): String
    fun releveEffacer()
    /** `performance.now()` du dernier passage de la page en arrière-plan ou au premier plan (0 s'il n'y en a pas eu). */
    fun dernierChangementVisibilite(): Double
    /** Met le relevé (résumé + creux + dernières lignes) dans le presse-papiers ; à appeler dans le geste du toucher. */
    fun copierReleve()
    /** Le résultat de la dernière copie : "" si elle n'a pas fini, sinon « copié, N lignes » ou la raison de l'échec. */
    fun statutCopie(): String
    /** Le journal des chargements de la page (n°, date, type de navigation, build) et les passages en arrière-plan. */
    fun chargements(): String
    /**
     * Compose ne transmet pas toujours `keyboardOptions` à l'élément de saisie du navigateur :
     * on lui pose `inputmode` ("text", "numeric", "decimal"), `autocapitalize` ("words",
     * "sentences", "none") et `enterkeyhint` à la main, au focus.
     */
    fun modeClavier(inputMode: String, autoCapitalize: String)
    /** Hauteur du clavier en px CSS (innerHeight − visualViewport), 0 s'il est fermé. */
    fun hauteurClavier(): Double
    /** Les mesures brutes, pour le diagnostic : "inner=… vv=… haut=…". */
    fun mesuresClavier(): String

    // ---- Banc d'essai (lot A) ----
    /** « autonome », « installee », « invite » ou « manuelle » (voir `boutonInstallerVisible`). */
    fun etatInstallation(): String
    /** Ouvre l'invite d'installation de Chromium ; à appeler dans le geste. « accepted », « dismissed » ou « indisponible ». */
    suspend fun demanderInstallation(): String
    /** Wake Lock : demande à garder l'écran allumé (redemandé au retour au premier plan). Rend l'état. */
    suspend fun ecranAllumeDemander(): String
    /** Relâche le Wake Lock. Rend l'état (« relâché »). */
    suspend fun ecranAllumeRelacher(): String
    /** « inactif », « actif », « refusé : <raison> », « indisponible », « relâché… ». */
    fun ecranAllumeEtat(): String
    /** L'environnement en JSON (user agent, platform, maxTouchPoints, écran, dpr, cœurs, langue, affichage, orientation). */
    fun environnement(): String
    /** Resource Timing : poids transféré et encodé de la page et de ses fichiers de même origine. */
    fun tailleTransferee(): String
    /** Le contrôle du précache par le Service Worker, en JSON (voir `lireControlePrecache`). */
    suspend fun controlePrecache(): String
    /** Une photo JPEG synthétique fabriquée dans un canevas : « O » + base64, ou « E » + raison. */
    suspend fun photoSynthetique(largeur: Int, hauteur: Int, graine: Int): String
    /** Un réglage du testeur gardé dans localStorage ; "" s'il n'y en a pas. */
    fun lireReglage(nom: String): String
    fun ecrireReglage(nom: String, valeur: String)
    /** Date et heure locales « aaaa-mm-jj hh:mm ». */
    fun dateLocale(): String
    /** Copie [texte] dans le presse-papiers (dans le geste) ; résultat dans `statutCopie()`. */
    fun copierTexte(texte: String)
    /** `navigator.share` (avec les fichiers .md et .json si possible), dans le geste : « O… » ou « E<raison> ». */
    suspend fun partager(titre: String, texte: String, json: String): String
    /** Vrai si rapport-config.js (version publiée) donne l'adresse et la clé de l'envoi. */
    fun envoiDisponible(): Boolean
    /** Envoie à la fonction Edge `signaler` : « O<url> » ou « E<code>|<détail> » (voir `lireResultatEnvoi`). */
    suspend fun envoyerRapport(titre: String, description: String, contexte: String, journal: String): String

    // ---- Parcours automatique (lot B) ----
    /** Le numéro de ce chargement de la page (localStorage, ne revient jamais à zéro). */
    fun numeroChargement(): Int
    /** navigator.onLine lu au tout début du chargement : faux pour une ouverture en mode avion. */
    fun enLigneAuChargement(): Boolean
    /** Date.now() : l'heure du mur, qui survit à un rechargement (contrairement à `msDepuisLancement`). */
    fun epochMs(): Double
    /** La partie visible de la page : « décalage haut|hauteur|innerHeight » en px CSS (voir `lireZoneVisible`). */
    fun zoneVisible(): String
}

data class MargesSures(val haut: Double, val bas: Double, val gauche: Double, val droite: Double)

/** Une photo telle que le navigateur l'a donnée : ses octets et son type MIME. */
class PhotoChoisie(val octets: ByteArray, val typeMime: String)
