package com.example.lebiais.sonde

import androidx.compose.foundation.layout.fillMaxWidth
import androidx.compose.material3.OutlinedTextField
import androidx.compose.material3.Text
import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.compose.ui.focus.onFocusChanged

/**
 * La remarque libre du testeur, avant « Envoyer le rapport » : une impression, un défaut, une question.
 * Elle est gardée dans les réglages tant qu'elle n'est pas envoyée, et le rapport déjà préparé
 * (celui que « Copier » et « Partager » utilisent sans rien attendre) est rafraîchi à chaque frappe.
 */
@Composable
fun ChampRemarque(valeur: String, surChangement: (String) -> Unit, modifier: Modifier = Modifier) {
    OutlinedTextField(
        value = valeur,
        onValueChange = { surChangement(it.take(LIMITE_REMARQUE)) },
        label = { Text("Remarques (facultatif)") },
        supportingText = { Text("Ce que vous avez remarqué : lenteurs, défauts, impressions, une question. Envoyé avec le rapport.") },
        minLines = 3,
        maxLines = 8,
        modifier = modifier.fillMaxWidth().onFocusChanged { if (it.isFocused) Navigateur.modeClavier("text", "sentences") },
    )
}
