private val ENCADRE = Color(0xFFF0E6CF)

/**
 * Le temps d'ouverture : `performance.now()` lu à la première image dessinée par
 * la racine, et celui de la fois d'avant, gardé dans localStorage.
 */
object Ouverture {
    /** En ms depuis le lancement de la page ; null tant qu'aucune image n'est dessinée. */
    var maintenant: Double? = null
        private set
    /** Le temps de l'ouverture précédente, "" s'il n'y en a pas. */
    var precedente: String = ""
        private set

    /** À appeler une fois, juste après la première image. */
    fun noter() {
        if (maintenant != null) return
        val ms = Navigateur.msDepuisLancement()
        precedente = Navigateur.ouvertureMemorisee()
        maintenant = ms
        Navigateur.noterOuverture(ms)
    }
}

private fun ms(valeur: Double): String = "${valeur.toLong()} ms"

/** Ce que la sonde sait d'elle-même et de l'appareil ; l'état d'installation et le temps d'ouverture. */
@Composable
fun EcranInfos() {
    var persistance by remember { mutableStateOf("…") }
    var serviceWorker by remember { mutableStateOf("…") }
    LaunchedEffect(Unit) {
        persistance = Navigateur.persistanceActuelle()
        serviceWorker = Navigateur.etatServiceWorker()
    }
    val marges = LocalMarges.current
    val installee = remember { Navigateur.estInstallee() }
    val ouverture = Ouverture.maintenant
    val precedente = Ouverture.precedente

    Column(
        Modifier.fillMaxWidth().verticalScroll(rememberScrollState()).padding(16.dp),
        verticalArrangement = Arrangement.spacedBy(10.dp),
    ) {
        if (!installee) {
            Column(Modifier.fillMaxWidth().background(ENCADRE).padding(12.dp), verticalArrangement = Arrangement.spacedBy(6.dp)) {
                Text("Pas encore installée", color = ENCRE, fontSize = 16.sp)
                Text(
                    "Sur iPhone et iPad, dans Safari : Partager → Sur l'écran d'accueil, puis ouvrir la sonde par son icône.",
                    color = ENCRE, fontSize = 14.sp,
                )
                Text(
                    "Attention : les données de l'onglet Safari et celles de l'icône sont séparées. " +
                        "Ce qui est écrit dans l'un n'existe pas dans l'autre : refaire les essais depuis l'icône.",
                    color = ENCRE, fontSize = 14.sp,
                )
            }
        }
        RapportDEssai(installee)
        Ligne("Version chargée", Navigateur.version)
        Ligne("Build", Navigateur.build())
        Ligne("Installée (écran d'accueil)", if (installee) "oui" else "non, ouverte dans un onglet")
        Ligne("Service Worker", serviceWorker)
        Ligne("Marge sûre haut", "${marges.haut.toInt()} px")
        Ligne("Marge sûre bas", "${marges.bas.toInt()} px")
        Ligne("Marge sûre gauche", "${marges.gauche.toInt()} px")
        Ligne("Marge sûre droite", "${marges.droite.toInt()} px")
        Ligne("Temps d'ouverture (1re image)", ouverture?.let { ms(it) } ?: "pas encore mesuré")
        Ligne("Temps d'ouverture précédent", precedente.ifEmpty { "aucun" }.let { if (it == "aucun") it else "$it ms" })
        Ligne("Chargements de la page", Navigateur.chargements())
        ReleveDeFluidite()
        Ligne("Moyen de stockage", Navigateur.moyenDeStockage())
        Ligne("Persistance", persistance)
        Ligne("User agent", Navigateur.userAgent())
    }
}

/**
 * Le rapport d'essai : qui teste, quelle version d'iOS (Safari ne la dit pas toujours), l'écran
 * allumé, et l'export (envoyer, copier, partager). Le rapport est préparé d'avance et rafraîchi :
 * copier et partager doivent partir du toucher sans rien attendre (iOS).
 */
@Composable
private fun RapportDEssai(installee: Boolean) {
    val scope = rememberCoroutineScope()
    val appareil = remember { appareilCourant() }
    var testeur by remember { mutableStateOf(Navigateur.lireReglage(Banc.REGLAGE_TESTEUR)) }
    var ios by remember { mutableStateOf(Navigateur.lireReglage(Banc.REGLAGE_IOS)) }
    var remarque by remember { mutableStateOf(Navigateur.lireReglage(Banc.REGLAGE_REMARQUE)) }
    var ecranAllume by remember { mutableStateOf(etatEcranAllume(appareil)) }
    var rapport by remember { mutableStateOf<Rapport?>(null) }
    var statut by remember { mutableStateOf("") }
    var ticket by remember { mutableStateOf("") }
    var envoiEnCours by remember { mutableStateOf(false) }
    val envoiPossible = remember { Navigateur.envoiDisponible() }

    LaunchedEffect(Unit) {
        while (true) {
            rapport = rapportCourant()
            delay(10_000)
        }
    }
    LaunchedEffect(Unit) {
        while (true) {
            ecranAllume = etatEcranAllume(appareil)
            delay(1000)
        }
    }

    Column(Modifier.fillMaxWidth().background(ENCADRE).padding(12.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
        Text("Rapport d'essai", color = ENCRE, fontSize = 16.sp)
        Text("Appareil d'après le navigateur : ${appareil.resume()}", color = ENCRE, fontSize = 14.sp)
        appareil.note?.let { Text(it, color = ENCRE.copy(alpha = 0.7f), fontSize = 13.sp) }
        OutlinedTextField(
            value = testeur,
            onValueChange = { testeur = it; Navigateur.ecrireReglage(Banc.REGLAGE_TESTEUR, it) },
            label = { Text("Testeur / appareil (libre, ex. « Marie, iPhone 15 »)") },
            singleLine = true,
            modifier = Modifier.fillMaxWidth().onFocusChanged { if (it.isFocused) Navigateur.modeClavier("text", "words") },
        )
        OutlinedTextField(
            value = ios,
            onValueChange = { ios = it; Navigateur.ecrireReglage(Banc.REGLAGE_IOS, it) },
            label = { Text("Version d'iOS indiquée par le testeur") },
            supportingText = { Text("Réglages → Général → Informations → Version d'iOS. Reprise dans chaque rapport.") },
            singleLine = true,
            modifier = Modifier.fillMaxWidth().onFocusChanged { if (it.isFocused) Navigateur.modeClavier("text", "none") },
        )
        Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(10.dp)) {
            Switch(
                checked = ecranAllume.startsWith("actif") || ecranAllume.startsWith("relâché par le navigateur"),
                onCheckedChange = { voulu ->
                    scope.launch(start = CoroutineStart.UNDISPATCHED) {
                        if (voulu) Navigateur.ecranAllumeDemander() else Navigateur.ecranAllumeRelacher()
                        ecranAllume = etatEcranAllume(appareil)
                    }
                },
            )
            Text("Garder l'écran allumé", color = ENCRE, fontSize = 15.sp)
        }
        Text("Écran allumé : $ecranAllume", color = ENCRE.copy(alpha = 0.8f), fontSize = 13.sp)
        ChampRemarque(remarque, { remarque = it; Navigateur.ecrireReglage(Banc.REGLAGE_REMARQUE, it); rapport = rapport?.copy(remarque = it) })
        Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
            Button(
                enabled = envoiPossible && !envoiEnCours,
                onClick = {
                    envoiEnCours = true
                    statut = "Envoi en cours…"
                    scope.launch {
                        try {
                            val r = rapportCourant().also { rapport = it }
                            val resultat = ExportRapport.envoyer(r)
                            ticket = resultat.url ?: ""
                            if (resultat.url != null) { remarque = ""; Navigateur.ecrireReglage(Banc.REGLAGE_REMARQUE, "") }
                            statut = if (resultat.url != null) "Rapport envoyé." else "${resultat.raison} Vous pouvez « Copier » ou « Partager »."
                        } finally { envoiEnCours = false }
                    }
                },
            ) { Text("Envoyer le rapport") }
            OutlinedButton(
                enabled = rapport != null,
                onClick = {
                    val r = rapport ?: return@OutlinedButton
                    ExportRapport.copier(r)
                    scope.launch { delay(700); statut = "Presse-papiers : " + Navigateur.statutCopie().ifEmpty { "en cours…" } }
                },
            ) { Text("Copier") }
            OutlinedButton(
                enabled = rapport != null,
                onClick = {
                    val r = rapport ?: return@OutlinedButton
                    scope.launch(start = CoroutineStart.UNDISPATCHED) { statut = ExportRapport.partager(r) }
                },
            ) { Text("Partager") }
        }
        if (!envoiPossible) Text("Envoi automatique indisponible dans cette version (« Copier » ou « Partager » restent possibles).", color = ENCRE.copy(alpha = 0.7f), fontSize = 13.sp)
        if (statut.isNotEmpty()) Text(statut, color = ENCRE, fontSize = 14.sp)
        if (ticket.isNotEmpty()) SelectionContainer { Text("Ticket : $ticket", color = ENCRE, fontSize = 14.sp) }
        Text(
            rapport?.let { "Rapport prêt : ${it.etapes.size} étape(s), ${it.releve.size} ligne(s) de relevé, ${it.enTexte().length} caractères." } ?: "Rapport en préparation…",
            color = ENCRE.copy(alpha = 0.6f), fontSize = 12.sp,
        )
    }
}

@Composable
private fun Ligne(titre: String, valeur: String) {
    Column {
        Text(titre, color = ENCRE.copy(alpha = 0.6f), fontSize = 12.sp)
        Text(valeur, color = ENCRE, fontSize = 15.sp)
    }
}

/** Le relevé de fluidité : un échantillon toutes les 5 s, dont on ne montre que le résumé et les derniers creux. */
@Composable
private fun ReleveDeFluidite() {
    var resume by remember { mutableStateOf(Fluidite.lire()) }
    var copie by remember { mutableStateOf("") }
    val scope = rememberCoroutineScope()
    Column {
        Text("Relevé de fluidité", color = ENCRE.copy(alpha = 0.6f), fontSize = 12.sp)
        Text(resume.enTexte(), color = ENCRE, fontSize = 15.sp)
        if (copie.isNotEmpty()) Text("Presse-papiers : $copie", color = ENCRE.copy(alpha = 0.8f), fontSize = 13.sp)
        Row {
            Text(
                "Actualiser",
                color = ENCRE,
                fontSize = 14.sp,
                modifier = Modifier.clickable { resume = Fluidite.lire() }.padding(end = 16.dp, top = 8.dp, bottom = 8.dp),
            )
            Text(
                "Copier le relevé",
                color = ENCRE,
                fontSize = 14.sp,
                modifier = Modifier.clickable {
                    Navigateur.copierReleve()
                    scope.launch { delay(700); copie = Navigateur.statutCopie().ifEmpty { "en cours…" } }
                }.padding(end = 16.dp, top = 8.dp, bottom = 8.dp),
            )
            Text(
                "Effacer le relevé",
                color = ENCRE,
                fontSize = 14.sp,
                modifier = Modifier.clickable { Navigateur.releveEffacer(); resume = Fluidite.lire() }.padding(vertical = 8.dp),
            )
        }
    }
}
